  <summary>Benchmark code</summary>

```csharp
using System;
using System.Buffers;
using System.Buffers.Text;
using System.Text;
using System.Text.Json;

using BenchmarkDotNet.Attributes;

namespace TimeSpanBenchmarks
{
	[MemoryDiagnoser]
	public class ParsingBenchmarks
	{
		private byte[]? _Utf8Data;

		[Params("00:00:00", "1:2:00:00", "-10675199.02:48:05.4775808")]
		public string? Input { get; set; }

		[GlobalSetup]
		public void GlobalSetup() => _Utf8Data = Encoding.UTF8.GetBytes($"\"{Input}\"");

		[Benchmark]
		public void TimeSpanParse()
		{
			Utf8JsonReader reader = new Utf8JsonReader(_Utf8Data);

			reader.Read();

			ReadOnlySpan<byte> value = reader.HasValueSequence ? reader.ValueSequence.ToArray() : reader.ValueSpan;

			int numberOfCharsRequired = value.Length;

			char[]? charArray = null;
			Span<char> valueAsChars;
			if (numberOfCharsRequired > 256)
			{
				charArray = ArrayPool<char>.Shared.Rent(numberOfCharsRequired);
				valueAsChars = charArray;
			}
			else
			{
				unsafe
				{
					char* ptr = stackalloc char[256];
					valueAsChars = new Span<char>(ptr, 256);
				}
			}

			int numberOfDecodedBytes = Encoding.UTF8.GetChars(value, valueAsChars);

			bool result = TimeSpan.TryParse(valueAsChars.Slice(0, numberOfDecodedBytes), out TimeSpan tsValue);

			if (charArray != null)
			{
				ArrayPool<char>.Shared.Return(charArray);
			}

			if (!result)
			{
				throw new JsonException();
			}
		}

		[Benchmark]
		public void Utf8ParserFallback()
		{
			Utf8JsonReader reader = new Utf8JsonReader(_Utf8Data);

			reader.Read();

			ReadOnlySpan<byte> source = reader.HasValueSequence ? reader.ValueSequence.ToArray() : reader.ValueSpan;

			bool result = Utf8Parser.TryParse(source, out TimeSpan tmpValue, out int bytesConsumed, 'c');

			/* Note: Utf8Parser.TryParse will return true for invalid input so
			   long as it starts with an integer. Example: "2021-06-18" or
			   "1$$$$$$$$$$". We need to check bytesConsumed to know if the
			   entire source was actually valid. */

			if (result && source.Length == bytesConsumed)
			{
				return;
			}

			result = Utf8Parser.TryParse(source, out tmpValue, out bytesConsumed, 'g');

			if (result && source.Length == bytesConsumed)
			{
				return;
			}

			throw new JsonException();
		}
	}
}
```
